    pub fn index_in(mut s: Str, mut xs: Strings, mut i: i64) -> i64 {
        loop {
            if null_p(xs) {
                return the::<i64>(-1i64);
            } else if string_eq_p(car(xs), s) {
                return i;
            } else {
                (xs, i) = (cdr(xs), i64_plus(i, 1i64));
                continue;
            }
        }
    }

    /// `%name`'s register.
    pub fn reg_of(s: Str) -> kayak_rt::data::DataAt<'static, Opd> {
        let n = after_prefix(s, str_lit!("%"));
        if i64_gt_eq(index_in(n, regs64(), 0i64), 0i64) {
            o_reg(index_in(n, regs64(), 0i64), 64i64)
        } else if i64_gt_eq(index_in(n, regs32(), 0i64), 0i64) {
            o_reg(index_in(n, regs32(), 0i64), 32i64)
        } else if i64_gt_eq(index_in(n, regs8(), 0i64), 0i64) {
            o_reg(index_in(n, regs8(), 0i64), 8i64)
        } else if string_eq_p(n, str_lit!("rip")) {
            o_reg(16i64, 64i64)
        } else {
            o_reg(not_yet(string_append(str_lit!("a register "), s)), 64i64)
        }
    }

    #[inline]
    pub fn reg_number(o: kayak_rt::data::DataAt<'static, Opd>) -> i64 {
        let tagcase_ = o;
        if Opd::__is_OReg(tagcase_) {
            let (n, w,) = Opd::__OReg(tagcase_);
            n
        } else {
            let other = tagcase_;
            not_yet(str_lit!("a register where one is wanted"))
        }
    }

    /// Where a `+` or `-` from `i` is, or -1.
    pub fn sign_at(mut s: Str, mut i: i64, mut n: i64) -> i64 {
        loop {
            if i64_gt_eq(i, n) {
                return the::<i64>(-1i64);
            } else if (char_eq_p(string_ref_i64(s, i), '+') || char_eq_p(string_ref_i64(s, i), '-')) {
                return i;
            } else {
                i = i64_plus(i, 1i64);
                continue;
            }
        }
    }

    /// A displacement: a number, a symbol, or `sym+n`, `sym-n`.
    pub fn disp_of(s: Str) -> Product_11_12<i64, Str> {
        if string_eq_p(s, str_lit!("")) {
            Product_11_12(the::<i64>(0i64), str_lit!(""))
        } else if number_text_p(s) {
            Product_11_12(number_of(s), str_lit!(""))
        } else {
            let k = sign_at(s, 1i64, string_length_i64(s));
            if i64_lt(k, 0i64) {
                Product_11_12(the::<i64>(0i64), s)
            } else {
                let (sym, n) = (substring(s, int_lit(0), i64_to_int(k)), number_of(substring(s, i64_to_int(i64_plus(k, 1i64)), string_length(s))));
                Product_11_12(if char_eq_p(string_ref(s, i64_to_int(k)), '-') {
                    i64_minus(0i64, n)
                } else {
                    n
                }, sym)
            }
        }
    }

    /// `D(%b)`, `D(%b,%i,s)`, `sym(%rip)`.
    pub fn mem_of(s: Str) -> kayak_rt::data::DataAt<'static, Opd> {
        let n = string_length_i64(s);
        let p = char_from(s, '(', 0i64, n);
        let d = disp_of(substring(s, int_lit(0), i64_to_int(p)));
        let a = if i64_lt(p, n) {
            i64_plus(p, 1i64)
        } else {
            n
        };
        let parts = split_commas(s, a, char_from(s, ')', a, n), 0i64, a, nil::<Str>());
        let base = if string_eq_p(car(parts), str_lit!("")) {
            the::<i64>(-1i64)
        } else {
            reg_number(reg_of(car(parts)))
        };
        if null_p(cdr(parts)) {
            o_mem(d.0, d.1, base, -1i64, 1i64)
        } else {
            o_mem(d.0, d.1, base, reg_number(reg_of(second_of(parts))), number_of(car(cdr(cdr(parts)))))
        }
    }

    #[inline]
    pub fn second_of(xs: Strings) -> Str {
        car(cdr(xs))
    }

    pub fn operand_of(s: Str) -> kayak_rt::data::DataAt<'static, Opd> {
        let c = string_ref(s, int_lit(0));
        if char_eq_p(c, '%') {
            reg_of(s)
        } else if char_eq_p(c, '$') {
            let v = after_prefix(s, str_lit!("$"));
            if number_text_p(v) {
                o_imm(number_of(v))
            } else {
                o_isym(v)
            }
        } else if char_eq_p(c, '*') {
            let v = after_prefix(s, str_lit!("*"));
            if char_eq_p(string_ref(v, int_lit(0)), '%') {
                o_ireg(reg_number(reg_of(v)))
            } else {
                let tagcase_ = mem_of(v);
                if Opd::__is_OMem(tagcase_) {
                    let (d, sym, b, i, sc,) = Opd::__OMem(tagcase_);
                    o_imem(d, sym, b)
                } else {
                    let other = tagcase_;
                    o_imem(0i64, str_lit!(""), 0i64)
                }
            }
        } else if i64_lt(char_from(s, '(', 0i64, string_length_i64(s)), string_length_i64(s)) {
            mem_of(s)
        } else {
            o_sym(s)
        }
    }

    /// `v`'s low `n` bytes, the least first, onto `acc` (reversed).
    pub fn le(mut v: i64, mut n: i64, mut acc: Bytes) -> Bytes {
        loop {
            if i64_lt_eq(n, 0i64) {
                return acc;
            } else {
                (v, n, acc) = (i64_shr(v, int_lit(8)), i64_minus(n, 1i64), kayak_rt::heap_cons(i64_and(v, 255i64), acc));
                continue;
            }
        }
    }

    #[inline]
    pub fn le_bytes(v: i64, n: i64) -> Bytes {
        reverse(le(v, n, nil::<i64>()))
    }

    #[inline]
    pub fn fits8_p(v: i64) -> bool {
        (i64_gt_eq(v, -128i64) && i64_lt_eq(v, 127i64))
    }

    #[inline]
    pub fn bit(b: bool, v: i64) -> i64 {
        if b {
            v
        } else {
            0i64
        }
    }

    // A REX prefix, or none where it would say nothing.
    pub fn rex(w: bool, r: i64, x: i64, b: i64) -> Bytes {
        let v = i64_plus(64i64, i64_plus(bit(w, 8i64), i64_plus(bit(i64_gt_eq(r, 8i64), 4i64), i64_plus(bit(i64_gt_eq(x, 8i64), 2i64), bit(i64_gt_eq(b, 8i64), 1i64)))));
        if i64_eq(v, 64i64) {
            nil::<i64>()
        } else {
            kayak_rt::heap_cons(v, kayak_rt::nil())
        }
    }

    #[inline]
    pub fn modrm(md: i64, rf: i64, rm: i64) -> i64 {
        i64_plus(i64_star(md, 64i64), i64_plus(i64_star(i64_and(rf, 7i64), 8i64), i64_and(rm, 7i64)))
    }

    // An instruction of opcode `op` (its bytes), register field `rf` (a
